if(uFrame%5==0)ret.x=.71-ret7.y;
// mix in img...
vec3 pic = texture(sampler_pic, uv_orig).xyz;
float lum = lum(pic);
float use_it = abs(lum - fract((audioLow+audioMid+audioHigh)*0.2));
use_it = clamp01(1.0 - use_it * 33.0);
ret = mix(ret, pic, use_it.xxx);
if(uFrame%7==0)ret.y=.71-ret7.z;
// darken over uTime
//ret -= 0.004;
//ret *= 0.99;
ret *= 0.97 + 0.03*clamp01( length(uv - uv_orig) * 200.0 );  // center only
}

